   /// Spawns `run(context.clone())` and, each time it panics, starts it again
   /// `LOOP_RESTART_DELAY_SECONDS` later with a fresh clone. A loop that returns is not restarted:
   /// the task then ends.
   pub fn spawn_supervised<T, F, Fut>(name: &'static str, context: T, run: F) -> JoinHandle<()>
   where
       T: Clone + Send + 'static,
       F: Fn(T) -> Fut + Send + 'static,
       Fut: Future<Output = ()> + Send + 'static,
